mapper.select:
SELECT p.project_id as id, p.project_name as name, p.description, p.start_date as startDate, p.end_date as endDate, p.budget, p.status, p.manager_id as managerId, e.name as managerName, d.department_name as departmentName, p.created_time as createdTime FROM project p LEFT JOIN employee e ON p.manager_id = e.employee_id LEFT JOIN department d ON p.department_id = d.department_id
AND p.project_name LIKE CONCAT('%', #{projectName}, '%')
AND p.status = #{status}
AND p.manager_id = #{managerId}
AND p.department_id = #{departmentId}
AND p.start_date >= #{startDate}
AND p.end_date <= #{endDate}
AND p.budget >= #{budgetMin}
AND p.budget <= #{budgetMax}
ORDER BY p.created_time DESC

mapper.delete:
DELETE
FROM project_employee
WHERE project_id = #{projectId}
  AND employee_id = #{employeeId}

mapper.select:
SELECT COUNT(*) as total_projects, COUNT(CASE WHEN status = 'ACTIVE' THEN 1 END) as active_projects, COUNT(CASE WHEN status = 'COMPLETED' THEN 1 END) as completed_projects, COUNT(CASE WHEN status = 'SUSPENDED' THEN 1 END) as suspended_projects, SUM(budget) as total_budget, AVG(budget) as avg_budget, MAX(budget) as max_budget, MIN(budget) as min_budget FROM project
AND department_id = #{departmentId}
AND start_date >= #{startDate}
AND end_date <= #{endDate}

SELECT d.department_name, COUNT(p.project_id) as project_count, SUM(p.budget) as total_budget, AVG(p.budget) as avg_budget, COUNT(CASE WHEN p.status = 'ACTIVE' THEN 1 END) as active_count, COUNT(CASE WHEN p.status = 'COMPLETED' THEN 1 END) as completed_count FROM project p JOIN department d ON p.department_id = d.department_id
AND YEAR(p.start_date) = #{year}
AND QUARTER(p.start_date) = #{quarter}
GROUP BY d.department_id, d.department_name ORDER BY total_budget DESC

SELECT pm.milestone_id, pm.milestone_name, pm.description, pm.target_date, pm.completion_date, pm.status, pm.priority, p.project_name FROM project_milestone pm JOIN project p ON pm.project_id = p.project_id
AND pm.project_id = #{projectId}
AND pm.status = #{status}
AND pm.priority = #{priority}
AND pm.target_date >= #{startDate}
AND pm.target_date <= #{endDate}
ORDER BY pm.target_date ASC
